<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use App\Http\Requests\Auth\LoginRequest; use App\Services\Audit\ActivityLogService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Validation\ValidationException;
class LoginController extends Controller { public function create(){return view('auth.login');} public function store(LoginRequest $request,ActivityLogService $audit){$credentials=$request->only('email','password');$credentials['is_active']=true;if(!Auth::attempt($credentials,$request->boolean('remember'))) throw ValidationException::withMessages(['email'=>'Email/password salah atau akun nonaktif.']);$request->session()->regenerate();$audit->record('auth','login',$request->user());return redirect()->intended('/dashboard');} public function destroy(Request $request,ActivityLogService $audit){$user=$request->user();if($user)$audit->record('auth','logout',$user);Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect('/login');} }
